// Per-grade vocabulary registry — maps GRADE_ORDER keys to each grade's
// vocabulary corpus for prefetch + lazy definition binding at that grade's
// curriculum start. the operator directive 2026-06-18. Nineteen lists, K→PhD,
// generated by .claude/scripts/gen-grade-vocab.mjs.
//
// ⭐⭐ THE LISTS ARE DATA AND THEY NOW LIVE AS DATA — `corpora/vocabulary/*.json`.
//
// They used to be nineteen `.js` modules, each one a single
// `export const G5_VOCABULARY = ['abacus','abandoned', …]` array: **676 KB and
// 5,179 lines of "data wearing a `.js` extension"**, in Sponge's words, counted
// by every tool as source and re-parsed by V8 as a program on every load.
// Moving them to JSON deletes those lines from the codebase without deleting one
// word of what she learns — the JSON was generated FROM the live exports and
// verified word-for-word against them before a single `.js` file was removed.
//
// ⚠ WHAT DID **NOT** CHANGE: the words, their order, their per-grade counts, and
// this module's public API. `gradeVocabularyFor(grade)` still returns the same
// array or `null`, and `fullJourneyVocabularyStats()` still computes over the
// same nineteen lists. A consumer cannot tell the difference, which is the point
// — this is a storage change, not a curriculum change.
//
// ⛔ SERVER-SIDE ONLY, AND THAT IS NOT AN ASSUMPTION — IT WAS MEASURED. Neither
// `curriculum.js` nor any `*-vocabulary.js` appears in `js/app.bundle.js`
// (checked by grepping the built bundle for `G5_VOCABULARY`, `antanaclasis` and
// `_teachWordDefinition`: zero hits for all three). The curriculum runs on the
// brain-server; the browser lane never walks grades. So reading these with `fs`
// costs the browser bundle nothing, because the browser bundle never had them.
//
// Lazy + cached per grade: only the active grade's list is read, and only once.

// ⚠ The dynamic imports are inside a `try` for the same reason `embeddings.js`
// documents at its own loader: this file is reachable from the browser build
// graph, and esbuild's `--platform=browser` cannot resolve `fs`/`path`. Inside a
// `try` that degrades to a runtime failure on a branch a browser never takes;
// outside one it is a hard build error and `npm run build` fails.
let _fsMod = null;
let _pathMod = null;
async function _node() {
  if (_fsMod && _pathMod) return { fs: _fsMod, path: _pathMod };
  try {
    _fsMod = await import('fs');
    _pathMod = await import('path');
  } catch (err) {
    throw new Error(`the vocabulary lists are read from disk and Node's fs/path are unavailable here: ${err?.message || err}`);
  }
  return { fs: _fsMod, path: _pathMod };
}

// The same resolution ladder `embeddings.js` uses, and for the same reason: the
// launchers `cd server` before starting node, so `process.cwd()` is
// `<repo>/server` while the data sits at `<repo>/corpora`. Resolving from `cwd`
// alone is exactly the bug that had the boot re-downloading a 1.04 GB table it
// already had.
function _candidates(path, rel) {
  const cwd = process.cwd();
  return [
    rel,
    path.join(cwd, rel),
    path.join(cwd, '..', rel),
    path.join(cwd, 'server', rel),
  ];
}

const VOCAB_DIR = 'corpora/vocabulary';

// grade key → its JSON file. The key IS the filename; there is no second naming
// scheme to keep in sync, which is one whole class of drift removed along with
// the nineteen exported symbol names this replaced.
const JOURNEY_GRADES = [
  'kindergarten', 'grade1', 'grade2', 'grade3', 'grade4', 'grade5',
  'grade6', 'grade7', 'grade8', 'grade9', 'grade10', 'grade11', 'grade12',
  'college1', 'college2', 'college3', 'college4', 'grad', 'phd',
];
const _cache = new Map();

/**
 * The vocabulary list for a grade, or `null` for a grade with no dedicated
 * corpus (pre-K — its inline runner vocab teaches as before).
 *
 * ⛔ A MISSING OR MALFORMED FILE THROWS. It does not return `null` and it does
 * not return `[]`. `null` is the documented answer for *"this grade has no
 * list"*, and a grade that HAS a list silently teaching zero words is the
 * failure this whole system exists to prevent — it would look like a completed
 * grade and deposit nothing.
 */
export async function gradeVocabularyFor(grade) {
  if (!JOURNEY_GRADES.includes(grade)) return null;
  if (_cache.has(grade)) return _cache.get(grade);

  const { fs, path } = await _node();
  const rel = `${VOCAB_DIR}/${grade}.json`;
  let found = null;
  for (const p of _candidates(path, rel)) {
    if (fs.existsSync(p)) { found = p; break; }
  }
  if (!found) {
    throw new Error(`vocabulary list missing for ${grade} — expected ${rel} (searched from ${process.cwd()}). This grade HAS a list; a grade that teaches zero words looks complete and deposits nothing.`);
  }

  const words = JSON.parse(fs.readFileSync(found, 'utf8'));
  if (!Array.isArray(words) || words.length === 0) {
    throw new Error(`${found} did not parse as a non-empty array of words`);
  }
  _cache.set(grade, words);
  return words;
}

/**
 * Kindergarten's list, by name.
 *
 * ⚠ Exists because `curriculum.js` reached for `K_VOCABULARY` directly at
 * several sites rather than going through the registry. Those sites now call
 * this, so there is exactly ONE piece of code that knows where the words live.
 */
export async function kVocabulary() {
  return gradeVocabularyFor('kindergarten');
}

// FULL-JOURNEY VOCABULARY STATS (2026-08-17). The dashboard's defs-taught
// denominator must reflect the WHOLE K→PhD journey, not just the active
// grade: the taught-set numerator counts every grade's learned words, so a
// grade-sized denominator lies the moment the walk crosses a grade boundary
// (it already had — the taught count once read 2,287 against K's 2,247).
// Loads every grade's list once, dedups (the AoA frequency bands overlap by
// design — a word taught once is taught), caches the result. ~56k strings,
// one-time cost, trivial RAM.
let _journeyStats = null;
export async function fullJourneyVocabularyStats() {
  if (_journeyStats) return _journeyStats;
  const uniq = new Set();
  let sum = 0;
  const perGrade = {};
  for (const g of JOURNEY_GRADES) {
    try {
      const v = await gradeVocabularyFor(g);
      const n = Array.isArray(v) ? v.length : 0;
      perGrade[g] = n;
      sum += n;
      if (Array.isArray(v)) for (const w of v) uniq.add(w);
    } catch {
      perGrade[g] = 0;   // a missing grade file must not sink the total
    }
  }
  _journeyStats = { unique: uniq.size, sum, perGrade };
  return _journeyStats;
}

export { JOURNEY_GRADES };
